package meter

import "time"

// Plan 是套餐的当前定义。修改定义只影响之后新保存的条件快照：之后开通的
// 订阅与之后新接受的换套餐安排按修改后的定义取得条件；已开通订阅保存的
// 快照与已接受安排锁定的条件不被改写。
type Plan struct {
	// ID 套餐唯一标识，不可为空。
	ID string
	// MonthlyFee 月费，单位为分，非负。
	MonthlyFee int64
	// IncludedUnits 每月包含用量，非负。
	IncludedUnits int64
	// OveragePrice 超出部分每单位价格（分/单位），非负。
	OveragePrice int64
	// TaxRateBasisPoints 税率，万分比，取值 [0, 10000]。
	TaxRateBasisPoints int64
}

// PlanTerms 是开通订阅或接受换套餐安排时保存的套餐条件快照。
// 之后修改套餐定义不影响已保存快照的计费。
type PlanTerms struct {
	PlanID             string
	MonthlyFee         int64
	IncludedUnits      int64
	OveragePrice       int64
	TaxRateBasisPoints int64
}

func termsOf(p Plan) PlanTerms {
	return PlanTerms{
		PlanID:             p.ID,
		MonthlyFee:         p.MonthlyFee,
		IncludedUnits:      p.IncludedUnits,
		OveragePrice:       p.OveragePrice,
		TaxRateBasisPoints: p.TaxRateBasisPoints,
	}
}

// Subscription 是一份有效订阅。每个账户只允许一份。
type Subscription struct {
	AccountID string
	// PlanID 开通时所依据的套餐标识。
	PlanID string
	// Terms 开通时刻保存的套餐条件快照。
	Terms PlanTerms
	// ActivatedAt 开通时刻，UTC。用量事件不得早于该时刻。
	ActivatedAt time.Time
}

// PlanChange 是一条尚未生效的换套餐安排。
type PlanChange struct {
	// TargetPlanID 目标套餐标识。
	TargetPlanID string
	// Terms 安排被接受时锁定的目标套餐完整条件快照；
	// 之后修改套餐定义不影响本安排。
	Terms PlanTerms
	// EffectivePeriod 生效账期：安排被接受时的下一个 UTC 自然月。
	EffectivePeriod Month
}

// PlanChangeResult 是换套餐安排成功提交的结果。
type PlanChangeResult struct {
	// Created 为 true 表示本次新建或替换了安排；
	// 为 false 表示目标套餐与已有安排相同，返回原安排，未重新取价。
	Created bool
	// Change 安排内容：目标套餐完整计费条件与生效账期。
	Change PlanChange
}

// SubscriptionCancellation 是一次按月取消订阅安排。
type SubscriptionCancellation struct {
	// EndAt 终止时刻（UTC）：取消请求时刻的下一个 UTC 自然月月初零点。
	// 终止时刻计入空档，不计入订阅期间。
	EndAt time.Time
}

// CancelSubscriptionResult 是取消订阅请求的结果。
type CancelSubscriptionResult struct {
	// Cancelled 为 true 表示本次新登记了取消安排；
	// 为 false 表示此前已安排取消，本次原样返回原终止时刻，不后移期限。
	Cancelled bool
	// Cancellation 取消安排内容。
	Cancellation SubscriptionCancellation
}

// termsEntry 是订阅条件历史中的一条：自 EffectivePeriod（含）起适用 Terms。
type termsEntry struct {
	effective Month
	terms     PlanTerms
}

// Event 是一条用量事件。
type Event struct {
	// AccountID 所属账户。
	AccountID string
	// EventID 事件标识，在同一账户内去重；不同账户可复用。
	EventID string
	// At 事件发生时刻，按此时刻归入账期（UTC 自然月）。
	At time.Time
	// Quantity 数量，非负。
	Quantity int64
}

// EventResult 是用量上报的结果。
type EventResult struct {
	// Accepted 为 true 表示该事件本次被接收并累计；
	// 为 false 表示这是此前已接收事件的完全相同重报，未再次累计。
	Accepted bool
	// Period 事件归入账期。
	Period Month
}

// Month 标识一个 UTC 自然月账期。
type Month struct {
	Year  int
	Month time.Month
}

// MonthOf 返回时刻 t（UTC）所在账期。
func MonthOf(t time.Time) Month {
	u := t.UTC()
	return Month{Year: u.Year(), Month: u.Month()}
}

// Start 返回账期开始时刻（UTC，当月 1 日 00:00:00）。
func (m Month) Start() time.Time {
	return time.Date(m.Year, m.Month, 1, 0, 0, 0, 0, time.UTC)
}

// End 返回账期结束时刻（次月 1 日 00:00:00 UTC），即下月账期开始。
func (m Month) End() time.Time {
	return m.Start().AddDate(0, 1, 0)
}

// Before 报告 m 是否早于 other。
func (m Month) Before(other Month) bool {
	if m.Year != other.Year {
		return m.Year < other.Year
	}
	return m.Month < other.Month
}

// String 返回 YYYY-MM 形式。
func (m Month) String() string {
	return m.Start().Format("2006-01")
}

// Bill 是一个账期的账单。出账后金额与用量明细固定，付款状态可继续变化。
type Bill struct {
	AccountID string
	Period    Month
	// Terms 出账采用的套餐条件：该账期当时适用的条件快照
	// （开通快照或某次已生效换套餐安排锁定的快照）。
	Terms PlanTerms
	// TotalUsage 账期内总用量。
	TotalUsage int64
	// IncludedUnits 包含额度。
	IncludedUnits int64
	// OverageUnits 超额用量 = max(0, TotalUsage - IncludedUnits)。
	OverageUnits int64
	// MonthlyFee 月费（分）。
	MonthlyFee int64
	// OverageFee 超额费用（分）。
	OverageFee int64
	// Tax 税额（分），对月费与超额费用之和按万分比四舍五入。
	Tax int64
	// TotalDue 应付总额（分）= MonthlyFee + OverageFee + Tax。
	TotalDue int64
	// Paid 已付金额（分）。
	Paid int64
	// Balance 剩余应付（分）= TotalDue - Paid。
	Balance int64
	// Settled 是否已付清；零金额账单出账时即为 true。
	Settled bool
	// DueAt 付款截止时刻：账期结束后七天（UTC）。
	DueAt time.Time
}

// Payment 是一次本地付款登记记录。
type Payment struct {
	AccountID string
	// PaymentID 付款标识，在同一账户内去重。
	PaymentID string
	// Period 付款所属账期（账单）。
	Period Month
	// Amount 付款金额（分），大于零且不超过账单当时余额。
	Amount int64
}

// PaymentResult 是付款登记结果。
type PaymentResult struct {
	// Registered 为 true 表示本次实际登记；false 表示完全相同重报。
	Registered bool
	Payment    Payment
	// BillBalance 登记后账单余额。
	BillBalance int64
	// Settled 登记后账单是否已付清。
	Settled bool
}

// Usage 是某个账期的累计用量查询结果。
type Usage struct {
	Period Month
	// Total 该账期已累计用量（出账后也保持固定）。
	Total int64
}

// AccountStatus 是账户当前状态查询结果。
type AccountStatus struct {
	AccountID string
	// Subscribed 当前是否有已实际生效的订阅。
	// 提前登记但开通时刻尚未到达的订阅不计入：以实际开通时刻为界，不按开通
	// 月份提前生效（开通当日凌晨仍为 false，到达开通时刻才为 true）。
	// 含已安排取消、尚未到终止时刻的等待期；到达终止时刻后即使没有上报用量
	// 或生成账单，也立即变为 false。
	Subscribed bool
	// Suspended 是否因到期欠费被停用（结清全部到期欠费账单后恢复；
	// 结清债务只解除停用，不复活已取消的订阅，也不让等待开通的订阅提前
	// 生效；等待开通本身不清除旧欠费，Subscribed 为 false 时仍可能停用）。
	Suspended bool
	// CurrentTerms 当前账期实际生效的套餐条件；无已生效订阅（含等待开通
	// 期间）时为零值。到达生效月份月初零点后，无需任何操作即为换套餐后
	// 的条件。
	CurrentTerms PlanTerms
	// PendingChange 尚未生效的换套餐安排；没有安排时为 nil。
	// 订阅未生效期间不允许安排，故等待开通时必为 nil。
	// 登记取消时会清除待生效安排，等待取消期间拒绝新安排。
	PendingChange *PlanChange
	// ScheduledEnd 已安排的订阅终止时刻（下一个 UTC 自然月月初）；
	// 未安排取消、等待开通期间或终止已发生时为 nil。等待取消期间
	// Subscribed 仍为 true。
	ScheduledEnd *time.Time
	// MonthlyUsage 各账期累计用量，按账期先后排列。
	MonthlyUsage []Usage
	// Bills 已生成账单的余额与付清状态，按账期先后排列。
	Bills []BillSummary
}

// BillSummary 是账单的付款状态摘要。
type BillSummary struct {
	Period   Month
	TotalDue int64
	Paid     int64
	Balance  int64
	Settled  bool
	DueAt    time.Time
}

package meter

import (
	"errors"
	"fmt"
)

// 业务错误。请求失败时通过 errors.Is 可判定具体原因。
var (
	// ErrInvalidArgument 表示参数非法：空标识、负数、税率越界或非法账期等。
	ErrInvalidArgument = errors.New("meter: invalid argument")
	// ErrOverflow 表示累计用量或金额超出 int64 范围。
	ErrOverflow = errors.New("meter: overflow")

	// ErrAccountExists 账户标识已存在。
	ErrAccountExists = errors.New("meter: account already exists")
	// ErrAccountNotFound 账户不存在。
	ErrAccountNotFound = errors.New("meter: account not found")

	// ErrPlanExists 套餐标识已存在。
	ErrPlanExists = errors.New("meter: plan already exists")
	// ErrPlanNotFound 套餐不存在。
	ErrPlanNotFound = errors.New("meter: plan not found")

	// ErrSubscriptionExists 该账户已有一份有效订阅。
	ErrSubscriptionExists = errors.New("meter: subscription already exists")
	// ErrSubscriptionNotFound 该账户尚未开通订阅。
	ErrSubscriptionNotFound = errors.New("meter: subscription not found")
	// ErrSubscriptionNotActivated 订阅开通时刻尚未到达。
	ErrSubscriptionNotActivated = errors.New("meter: subscription not activated")
	// ErrPlanChangeSamePlan 换套餐安排的目标套餐与当前生效套餐相同。
	ErrPlanChangeSamePlan = errors.New("meter: plan change target is current plan")
	// ErrPlanChangeNotFound 没有待生效的换套餐安排。
	ErrPlanChangeNotFound = errors.New("meter: plan change not found")
	// ErrPlanChangeWhileCancelling 等待取消期间拒绝新的换套餐安排。
	ErrPlanChangeWhileCancelling = errors.New("meter: plan change rejected while cancellation pending")
	// ErrResubscribeBeforeEnd 重新开通时刻早于上次订阅终止时刻。
	ErrResubscribeBeforeEnd = errors.New("meter: resubscribe before previous end time")

	// ErrEventConflict 事件标识相同但时刻或数量不同。
	ErrEventConflict = errors.New("meter: event conflict")
	// ErrEventBeforeSubscription 事件发生时刻早于订阅开通时刻。
	ErrEventBeforeSubscription = errors.New("meter: event before subscription")
	// ErrEventInFuture 事件发生时刻晚于当前时刻。
	ErrEventInFuture = errors.New("meter: event in the future")
	// ErrMonthBilled 该账期已出账，拒绝首次出现的新事件。
	ErrMonthBilled = errors.New("meter: month already billed")
	// ErrSuspended 账户因到期欠费被停用，拒绝新用量。
	ErrSuspended = errors.New("meter: account suspended")

	// ErrBillNotFound 指定账期尚未生成账单。
	ErrBillNotFound = errors.New("meter: bill not found")
	// ErrBillBeforeSubscription 只能为开通当月及以后生成账单。
	ErrBillBeforeSubscription = errors.New("meter: bill period before subscription")
	// ErrBillMonthNotEnded 只能为已经结束的月份生成账单。
	ErrBillMonthNotEnded = errors.New("meter: bill period has not ended")

	// ErrPaymentConflict 付款标识相同但账单或金额不同。
	ErrPaymentConflict = errors.New("meter: payment conflict")
	// ErrPaymentExceedsBalance 付款金额大于账单当前余额。
	ErrPaymentExceedsBalance = errors.New("meter: payment exceeds balance")
)

func invalidf(format string, args ...any) error {
	return fmt.Errorf("%w: %s", ErrInvalidArgument, fmt.Sprintf(format, args...))
}

package meter_test

import (
	"errors"
	"fmt"
	"time"

	"github.com/descikazuyq/subscription-meter/meter"
)

// ExampleService_schedulePlanChange 演示“修改套餐定义”与“给账户安排换套餐”
// 的区别：UpdatePlan 只影响之后新保存的条件快照（之后开通的订阅与之后新
// 接受的换套餐安排），不改写账户正在使用的条件，也不改写此前已接受的换
// 套餐安排；SchedulePlanChange 在被接受时锁定目标套餐当时的完整条件。
//
// 账户 acct-switch 2026-01-01 00:00 UTC 开通 plan-a（月费 1000 分、包含
// 10 单位、超额单价 100 分、税率 10%），一月中旬安排二月换到 plan-b
// （当时定义为月费 2000 分、包含 20 单位、超额单价 200 分、税率 6%）。
// 随后 UpdatePlan 把 plan-b 的定义改为月费 5000 分、包含 5 单位、超额
// 单价 900 分、税率 25%：已接受的安排不被改写，再次安排同一目标返回原
// 安排（Created=false），不重新取价。二月月初零点（UTC）后直接查询即
// 显示锁定的 plan-b 条件；一月账单仍按 plan-a 计费，二月账单按锁定的
// plan-b 条件计费，修改后的定义不混入这次切换的计费。
//
// 示例通过 NewServiceWithClock 注入可推进的时钟，输出不依赖运行当天日期。
func ExampleService_schedulePlanChange() {
	const accountID = "acct-switch"
	jan := meter.MonthOf(mustParseTime("2026-01-01T00:00:00Z"))
	feb := meter.MonthOf(mustParseTime("2026-02-01T00:00:00Z"))

	// 可推进的时钟：初始当前时刻为 2026-01-15 12:00 UTC（一月中旬），
	// 之后逐段推进到二月、三月，复制后在任何真实日期运行结果都相同。
	now := mustParseTime("2026-01-15T12:00:00Z")
	s := meter.NewServiceWithClock(func() time.Time { return now })

	if err := s.CreateAccount(accountID); err != nil {
		panic(err)
	}
	// 套餐 plan-a：月费 1000 分、包含 10 单位、超额单价 100 分、税率 10%。
	if err := s.CreatePlan(meter.Plan{
		ID: "plan-a", MonthlyFee: 1000, IncludedUnits: 10,
		OveragePrice: 100, TaxRateBasisPoints: 1000,
	}); err != nil {
		panic(err)
	}
	// 套餐 plan-b 当前定义：月费 2000 分、包含 20 单位、超额单价 200 分、税率 6%。
	if err := s.CreatePlan(meter.Plan{
		ID: "plan-b", MonthlyFee: 2000, IncludedUnits: 20,
		OveragePrice: 200, TaxRateBasisPoints: 600,
	}); err != nil {
		panic(err)
	}
	// 账户一月起使用 plan-a。
	if err := s.Subscribe(accountID, "plan-a", mustParseTime("2026-01-01T00:00:00Z")); err != nil {
		panic(err)
	}

	// 一月用量 15 单位，超出 plan-a 包含的 10 单位。
	ev, err := s.RecordEvent(meter.Event{
		AccountID: accountID, EventID: "e-jan",
		At: mustParseTime("2026-01-10T00:00:00Z"), Quantity: 15,
	})
	if err != nil {
		panic(err)
	}
	fmt.Printf("event e-jan accepted=%t period=%s\n", ev.Accepted, ev.Period)

	// 一月中旬安排二月换到 plan-b：安排被接受时锁定目标套餐当时的
	// 完整条件与生效账期（请求被接受时的下一个 UTC 自然月）。
	r, err := s.SchedulePlanChange(accountID, "plan-b")
	if err != nil {
		panic(err)
	}
	fmt.Printf("schedule    created=%t target=%s effective=%s monthlyFee=%d includedUnits=%d overagePrice=%d taxRateBasisPoints=%d\n",
		r.Created, r.Change.TargetPlanID, r.Change.EffectivePeriod,
		r.Change.Terms.MonthlyFee, r.Change.Terms.IncludedUnits,
		r.Change.Terms.OveragePrice, r.Change.Terms.TaxRateBasisPoints)

	// 安排当月仍按旧套餐：查询仍显示 plan-a，待生效安排为 plan-b。
	st, err := s.Status(accountID)
	if err != nil {
		panic(err)
	}
	fmt.Printf("status      current=%s monthlyFee=%d pending=%s pendingEffective=%s\n",
		st.CurrentTerms.PlanID, st.CurrentTerms.MonthlyFee,
		st.PendingChange.TargetPlanID, st.PendingChange.EffectivePeriod)

	// 修改 plan-b 的定义：月费、包含额度、超额单价、税率全部改变。
	// 修改只影响之后新保存的条件快照，不改写已接受的安排。
	if err := s.UpdatePlan(meter.Plan{
		ID: "plan-b", MonthlyFee: 5000, IncludedUnits: 5,
		OveragePrice: 900, TaxRateBasisPoints: 2500,
	}); err != nil {
		panic(err)
	}

	// 再次安排同一个目标 plan-b：返回原安排，Created=false，条件仍是
	// 首次安排时锁定的快照，不按修改后的定义重新取价。
	r, err = s.SchedulePlanChange(accountID, "plan-b")
	if err != nil {
		panic(err)
	}
	fmt.Printf("reschedule  created=%t target=%s effective=%s monthlyFee=%d includedUnits=%d overagePrice=%d taxRateBasisPoints=%d\n",
		r.Created, r.Change.TargetPlanID, r.Change.EffectivePeriod,
		r.Change.Terms.MonthlyFee, r.Change.Terms.IncludedUnits,
		r.Change.Terms.OveragePrice, r.Change.Terms.TaxRateBasisPoints)

	// 待生效安排的条件也没有被修改后的定义改写。
	st, err = s.Status(accountID)
	if err != nil {
		panic(err)
	}
	fmt.Printf("after update current=%s pending=%s pendingMonthlyFee=%d pendingTaxRateBasisPoints=%d\n",
		st.CurrentTerms.PlanID, st.PendingChange.TargetPlanID,
		st.PendingChange.Terms.MonthlyFee, st.PendingChange.Terms.TaxRateBasisPoints)

	// 推进到 2026-02-01 00:00 UTC（二月月初零点）：安排自动生效，
	// 直接查询即显示锁定的 plan-b 条件，待生效安排消失，
	// 无须先上报用量或生成账单。
	now = mustParseTime("2026-02-01T00:00:00Z")
	st, err = s.Status(accountID)
	if err != nil {
		panic(err)
	}
	fmt.Printf("status      current=%s monthlyFee=%d includedUnits=%d overagePrice=%d taxRateBasisPoints=%d pending=%v\n",
		st.CurrentTerms.PlanID, st.CurrentTerms.MonthlyFee,
		st.CurrentTerms.IncludedUnits, st.CurrentTerms.OveragePrice,
		st.CurrentTerms.TaxRateBasisPoints, st.PendingChange)

	// “重复安排返回原安排”仅限于安排尚未生效时：生效后 plan-b 已是
	// 当前套餐，再安排它按现有规则返回同套餐错误。
	_, err = s.SchedulePlanChange(accountID, "plan-b")
	fmt.Printf("same plan   errSamePlan=%t\n", errors.Is(err, meter.ErrPlanChangeSamePlan))

	// 一月账期已结束，为一月出账：仍按 plan-a 收完整月费、给完整额度。
	// 用量 15，超额 5 × 100 = 500 分；税 (1000+500) × 10% = 150 分。
	janBill, err := s.CreateBill(accountID, jan)
	if err != nil {
		panic(err)
	}
	fmt.Printf("bill jan    plan=%s totalUsage=%d monthlyFee=%d includedUnits=%d overageUnits=%d overageFee=%d tax=%d totalDue=%d dueAt=%s\n",
		janBill.Terms.PlanID, janBill.TotalUsage, janBill.MonthlyFee,
		janBill.IncludedUnits, janBill.OverageUnits, janBill.OverageFee,
		janBill.Tax, janBill.TotalDue, janBill.DueAt.Format(time.RFC3339))

	// 一月账单截止 2026-02-08 00:00 UTC。当前时刻推进到 2 月 10 日：
	// 若不结清，欠费停用会阻止二月上报新用量，因此先正常登记付款。
	now = mustParseTime("2026-02-10T00:00:00Z")
	pay, err := s.RecordPayment(accountID, "pay-jan", jan, janBill.TotalDue)
	if err != nil {
		panic(err)
	}
	fmt.Printf("payment     registered=%t paymentID=%s amount=%d billBalance=%d settled=%t\n",
		pay.Registered, pay.Payment.PaymentID, pay.Payment.Amount, pay.BillBalance, pay.Settled)

	// 二月用量 25 单位，超出锁定的 plan-b 包含的 20 单位。
	ev, err = s.RecordEvent(meter.Event{
		AccountID: accountID, EventID: "e-feb",
		At: mustParseTime("2026-02-10T00:00:00Z"), Quantity: 25,
	})
	if err != nil {
		panic(err)
	}
	fmt.Printf("event e-feb accepted=%t period=%s\n", ev.Accepted, ev.Period)

	// 二月账期结束后为二月出账：按安排时锁定的 plan-b 条件计费
	// （月费 2000 分，不是修改后的 5000 分）。用量 25，超额
	// 5 × 200 = 1000 分；税 (2000+1000) × 6% = 180 分。
	now = mustParseTime("2026-03-01T00:00:00Z")
	febBill, err := s.CreateBill(accountID, feb)
	if err != nil {
		panic(err)
	}
	fmt.Printf("bill feb    plan=%s totalUsage=%d monthlyFee=%d includedUnits=%d overageUnits=%d overageFee=%d tax=%d totalDue=%d dueAt=%s\n",
		febBill.Terms.PlanID, febBill.TotalUsage, febBill.MonthlyFee,
		febBill.IncludedUnits, febBill.OverageUnits, febBill.OverageFee,
		febBill.Tax, febBill.TotalDue, febBill.DueAt.Format(time.RFC3339))

	// 二月出账后查询一月账单：超额费用、税额与总应付保持原样。
	janAgain, err := s.GetBill(accountID, jan)
	if err != nil {
		panic(err)
	}
	fmt.Printf("get bill jan plan=%s totalUsage=%d overageFee=%d tax=%d totalDue=%d\n",
		janAgain.Terms.PlanID, janAgain.TotalUsage, janAgain.OverageFee,
		janAgain.Tax, janAgain.TotalDue)

	// Output:
	// event e-jan accepted=true period=2026-01
	// schedule    created=true target=plan-b effective=2026-02 monthlyFee=2000 includedUnits=20 overagePrice=200 taxRateBasisPoints=600
	// status      current=plan-a monthlyFee=1000 pending=plan-b pendingEffective=2026-02
	// reschedule  created=false target=plan-b effective=2026-02 monthlyFee=2000 includedUnits=20 overagePrice=200 taxRateBasisPoints=600
	// after update current=plan-a pending=plan-b pendingMonthlyFee=2000 pendingTaxRateBasisPoints=600
	// status      current=plan-b monthlyFee=2000 includedUnits=20 overagePrice=200 taxRateBasisPoints=600 pending=<nil>
	// same plan   errSamePlan=true
	// bill jan    plan=plan-a totalUsage=15 monthlyFee=1000 includedUnits=10 overageUnits=5 overageFee=500 tax=150 totalDue=1650 dueAt=2026-02-08T00:00:00Z
	// payment     registered=true paymentID=pay-jan amount=1650 billBalance=0 settled=true
	// event e-feb accepted=true period=2026-02
	// bill feb    plan=plan-b totalUsage=25 monthlyFee=2000 includedUnits=20 overageUnits=5 overageFee=1000 tax=180 totalDue=3180 dueAt=2026-03-08T00:00:00Z
	// get bill jan plan=plan-a totalUsage=15 overageFee=500 tax=150 totalDue=1650
}

