1	package meter
2	
3	import (
4		"errors"
5		"sync"
6		"testing"
7		"time"
8	)
9	
10	func apr(y int) Month { return Month{Year: y, Month: time.April} }
11	
12	func mustCancel(t *testing.T, s *Service, acct string) CancelSubscriptionResult {
13		t.Helper()
14		r, err := s.CancelSubscription(acct)
15		if err != nil {
16			t.Fatalf("cancel %s: %v", acct, err)
17		}
18		return r
19	}
20	
21	// TestCancelSubscriptionScheduleEndAndStatus 覆盖终止时刻、重复取消不后移、
22	// 等待期与终止后的状态展示，以及当月完整计费、历史可查。
23	func TestCancelSubscriptionScheduleEndAndStatus(t *testing.T) {
24		s, clk := newTestService(utc(2026, 1, 15, 12, 0))
25		mustPlan(t, s, planDef("a", 1000, 10, 10, 0))
26		mustAccount(t, s, "u")
27		mustSubscribe(t, s, "u", "a", utc(2026, 1, 1, 0, 0))
28	
29		// 终止时刻为请求时刻的下一个 UTC 自然月月初。
30		r := mustCancel(t, s, "u")
31		wantEnd := utc(2026, 2, 1, 0, 0)
32		if !r.Cancelled || !r.Cancellation.EndAt.Equal(wantEnd) {
33			t.Fatalf("cancel result = %+v, want end %v", r, wantEnd)
34		}
35		// 重复取消始终返回原终止时刻，不后移。
36		clk.t = utc(2026, 1, 20, 9, 0)
37		r2 := mustCancel(t, s, "u")
38		if r2.Cancelled || !r2.Cancellation.EndAt.Equal(wantEnd) {
39			t.Fatalf("repeat cancel = %+v, want same end %v", r2, wantEnd)
40		}
41	
42		// 等待取消期间仍显示有有效订阅，并展示终止时刻。
43		st, _ := s.Status("u")
44		if !st.Subscribed || st.ScheduledEnd == nil || !st.ScheduledEnd.Equal(wantEnd) {
45			t.Fatalf("status while cancelling: %+v", st)
46		}
47		if st.CurrentTerms.PlanID != "a" || st.PendingChange != nil {
48			t.Fatalf("terms/pending while cancelling: cur=%+v pending=%+v", st.CurrentTerms, st.PendingChange)
49		}
50	
51		// 当月照常接收用量。
52		clk.t = utc(2026, 1, 25, 12, 0)
53		if _, err := s.RecordEvent(Event{AccountID: "u", EventID: "j", At: utc(2026, 1, 25, 0, 0), Quantity: 15}); err != nil {
54			t.Fatalf("usage in cancellation month: %v", err)
55		}
56	
57		// 到达终止时刻：即使没有再上报用量或生成账单，也立即无有效订阅、无当前套餐、
58		// 无待切换、无终止安排。
59		clk.t = utc(2026, 2, 1, 0, 0)
60		st, _ = s.Status("u")
61		if st.Subscribed || st.CurrentTerms != (PlanTerms{}) || st.PendingChange != nil || st.ScheduledEnd != nil {
62			t.Fatalf("status at end: %+v", st)
63		}
64	
65		// 历史用量继续可查。
66		if u, _ := s.MonthlyUsage("u", jan(2026)); u.Total != 15 {
67			t.Fatalf("jan usage after end = %d", u.Total)
68		}
69		if len(st.MonthlyUsage) != 1 || st.MonthlyUsage[0].Period != jan(2026) {
70			t.Fatalf("history usage lost: %+v", st.MonthlyUsage)
71		}
72	
73		// 取消当月按完整月费与额度计费，不按天退款：
74		// fee 1000 + 超额 (15-10)*10 = 1500。
75		b := mustBill(t, s, "u", jan(2026))
76		if b.MonthlyFee != 1000 || b.OverageUnits != 5 || b.OverageFee != 50 || b.TotalDue != 1050 {
77			t.Fatalf("cancellation month bill not full terms: %+v", b)
78		}
79		// 历史账单在状态中继续可查。
80		st, _ = s.Status("u")
81		if len(st.Bills) != 1 || st.Bills[0].Period != jan(2026) {
82			t.Fatalf("history bills lost: %+v", st.Bills)
83		}
84	}
85	
86	// TestUndoCancellation 覆盖撤回：生效前可撤回、无安排也成功、终止后失败、
87	// 撤回不恢复被清除的换套餐安排。
88	func TestUndoCancellation(t *testing.T) {
89		s, clk := newTestService(utc(2026, 1, 15, 12, 0))
90		mustPlan(t, s, planDef("a", 1000, 10, 5, 0))
91		mustPlan(t, s, planDef("b", 2000, 20, 8, 0))
92		mustAccount(t, s, "u")
93		mustSubscribe(t, s, "u", "a", utc(2026, 1, 1, 0, 0))
94	
95		// 有效订阅没有取消安排时撤回也成功。
96		if err := s.UndoCancelSubscription("u"); err != nil {
97			t.Fatalf("undo without arrangement: %v", err)
98		}
99	
100		// 登记的换套餐安排会被取消清除；撤回取消不恢复它。
101		mustSchedule(t, s, "u", "b")
102		mustCancel(t, s, "u")
103		st, _ := s.Status("u")
104		if st.PendingChange != nil || st.ScheduledEnd == nil {
105			t.Fatalf("pending not cleared by cancel: %+v", st)
106		}
107		if err := s.UndoCancelSubscription("u"); err != nil {
108			t.Fatalf("undo: %v", err)
109		}
110		st, _ = s.Status("u")
111		if st.Subscribed != true || st.ScheduledEnd != nil || st.PendingChange != nil {
112			t.Fatalf("status after undo: %+v", st)
113		}
114		// 撤回后订阅照常延续：2 月仍是原套餐且可接收用量。
115		clk.t = utc(2026, 2, 10, 0, 0)
116		st, _ = s.Status("u")
117		if !st.Subscribed || st.CurrentTerms.PlanID != "a" {
118			t.Fatalf("subscription ended despite undo: %+v", st)
119		}
120		if _, err := s.RecordEvent(Event{AccountID: "u", EventID: "f", At: utc(2026, 2, 5, 0, 0), Quantity: 1}); err != nil {
121			t.Fatalf("event after undo: %v", err)
122		}
123	
124		// 终止后撤回失败。
125		mustCancel(t, s, "u") // clk 2/10 -> end 3/1
126		clk.t = utc(2026, 3, 1, 0, 0)
127		if err := s.UndoCancelSubscription("u"); !errors.Is(err, ErrSubscriptionNotFound) {
128			t.Fatalf("undo after end = %v", err)
129		}
130	
131		// 引用错误。
132		if err := s.UndoCancelSubscription("ghost"); !errors.Is(err, ErrAccountNotFound) {
133			t.Fatalf("undo ghost: %v", err)
134		}
135		mustAccount(t, s, "nosub")
136		if err := s.UndoCancelSubscription("nosub"); !errors.Is(err, ErrSubscriptionNotFound) {
137			t.Fatalf("undo without subscription: %v", err)
138		}
139	}
140	
141	// TestCancelInteractsWithPlanChanges 覆盖清除待生效安排、等待期拒绝新安排，
142	// 以及恰在换套餐生效月初时先承认切换、取消从再下一月生效。
143	func TestCancelInteractsWithPlanChanges(t *testing.T) {
144		s, clk := newTestService(utc(2026, 1, 15, 12, 0))
145		mustPlan(t, s, planDef("a", 1000, 10, 5, 0))
146		mustPlan(t, s, planDef("b", 2000, 20, 8, 0))
147		mustAccount(t, s, "u")
148		mustSubscribe(t, s, "u", "a", utc(2026, 1, 1, 0, 0))
149	
150		// 登记取消清除尚未生效的安排，等待期间拒绝新安排。
151		mustSchedule(t, s, "u", "b")
152		r := mustCancel(t, s, "u")
153		if !r.Cancellation.EndAt.Equal(utc(2026, 2, 1, 0, 0)) {
154			t.Fatalf("end = %v", r.Cancellation.EndAt)
155		}
156		st, _ := s.Status("u")
157		if st.PendingChange != nil {
158			t.Fatalf("pending survived cancel: %+v", st.PendingChange)
159		}
160		if _, err := s.SchedulePlanChange("u", "b"); !errors.Is(err, ErrPlanChangeWhileCancelling) {
161			t.Fatalf("schedule while cancelling: %v", err)
162		}
163		// 失败的安排不留痕迹。
164		st, _ = s.Status("u")
165		if st.PendingChange != nil || st.ScheduledEnd == nil {
166			t.Fatalf("state after rejected schedule: %+v", st)
167		}
168	
169		// 恰在换套餐生效的月初：先承认该次切换，取消从再下一月生效。
170		mustAccount(t, s, "v")
171		mustSubscribe(t, s, "v", "a", utc(2026, 1, 1, 0, 0))
172		mustSchedule(t, s, "v", "b")
173		clk.t = utc(2026, 2, 1, 0, 0)
174		rv := mustCancel(t, s, "v")
175		if !rv.Cancellation.EndAt.Equal(utc(2026, 3, 1, 0, 0)) {
176			t.Fatalf("boundary cancel end = %v, want 2026-03-01", rv.Cancellation.EndAt)
177		}
178		st, _ = s.Status("v")
179		if st.CurrentTerms.PlanID != "b" || st.PendingChange != nil {
180			t.Fatalf("switch not acknowledged before cancel: %+v", st)
181		}
182		// 终止后该段以 b 套餐条件记入历史。
183		clk.t = utc(2026, 3, 1, 0, 0)
184		st, _ = s.Status("v")
185		if st.Subscribed {
186			t.Fatalf("v still subscribed after end")
187		}
188		febBill := mustBill(t, s, "v", feb(2026))
189		if febBill.Terms.PlanID != "b" || febBill.MonthlyFee != 2000 {
190			t.Fatalf("feb bill after boundary cancel: %+v", febBill)
191		}
192	}
193	
194	// TestCancelSubscriptionErrors 覆盖不能取消的情形。
195	func TestCancelSubscriptionErrors(t *testing.T) {
196		s, clk := newTestService(utc(2026, 1, 15, 12, 0))
197		mustPlan(t, s, planDef("a", 1000, 10, 5, 0))
198		mustAccount(t, s, "u")
199		mustAccount(t, s, "late")
200		mustSubscribe(t, s, "u", "a", utc(2026, 1, 1, 0, 0))
201		// 开通时刻尚未到达。
202		mustSubscribe(t, s, "late", "a", utc(2026, 1, 20, 0, 0))
203		mustAccount(t, s, "never")
204	
205		if _, err := s.CancelSubscription("ghost"); !errors.Is(err, ErrAccountNotFound) {
206			t.Fatalf("missing account: %v", err)
207		}
208		if _, err := s.CancelSubscription(""); !errors.Is(err, ErrInvalidArgument) {
209			t.Fatalf("empty account: %v", err)
210		}
211		if _, err := s.CancelSubscription("never"); !errors.Is(err, ErrSubscriptionNotFound) {
212			t.Fatalf("never subscribed: %v", err)
213		}
214		if _, err := s.CancelSubscription("late"); !errors.Is(err, ErrSubscriptionNotActivated) {
215			t.Fatalf("not activated: %v", err)
216		}
217	
218		// 终止后再取消失败。
219		mustCancel(t, s, "u")
220		clk.t = utc(2026, 2, 1, 0, 0)
221		if _, err := s.CancelSubscription("u"); !errors.Is(err, ErrSubscriptionNotFound) {
222			t.Fatalf("cancel after end: %v", err)
223		}
224	}
225	
226	// TestCancelWhileSuspended 欠费停用不妨碍取消，也不免除债务。
227	func TestCancelWhileSuspended(t *testing.T) {
228		s, clk := newTestService(utc(2026, 1, 20, 12, 0))
229		mustPlan(t, s, planDef("a", 1000, 0, 0, 0))
230		mustAccount(t, s, "u")
231		mustSubscribe(t, s, "u", "a", utc(2026, 1, 1, 0, 0))
232		if _, err := s.RecordEvent(Event{AccountID: "u", EventID: "e", At: utc(2026, 1, 10, 0, 0), Quantity: 1}); err != nil {
233			t.Fatal(err)
234		}
235		clk.t = utc(2026, 2, 1, 0, 0)
236		if _, err := s.CreateBill("u", jan(2026)); err != nil {
237			t.Fatal(err)
238		}
239		clk.t = utc(2026, 2, 8, 0, 0)
240		st, _ := s.Status("u")
241		if !st.Suspended {
242			t.Fatal("should be suspended")
243		}
244	
245		// 停用期间仍可取消。
246		r := mustCancel(t, s, "u")
247		if !r.Cancellation.EndAt.Equal(utc(2026, 3, 1, 0, 0)) {
248			t.Fatalf("suspended cancel end = %v", r.Cancellation.EndAt)
249		}
250		st, _ = s.Status("u")
251		if !st.Suspended || !st.Subscribed {
252			t.Fatalf("cancel changed suspension/debt: %+v", st)
253		}
254		// 终止后欠费依旧存在。
255		clk.t = utc(2026, 3, 1, 0, 0)
256		st, _ = s.Status("u")
257		if st.Subscribed || !st.Suspended {
258			t.Fatalf("debt cleared at end: %+v", st)
259		}
260		if len(st.Bills) != 1 || st.Bills[0].Balance != 1000 {
261			t.Fatalf("bill missing after end: %+v", st.Bills)
262		}
263		// 结清只解除停用，不复活已取消的订阅。
264		if _, err := s.RecordPayment("u", "p", jan(2026), 1000); err != nil {
265			t.Fatal(err)
266		}
267		st, _ = s.Status("u")
268		if st.Suspended || st.Subscribed {
269			t.Fatalf("payment revived subscription: %+v", st)
270		}
271	}
272	
273	// TestEventMembershipAcrossSegments 事件按发生时刻判断订阅期间归属：
274	// 开通时刻计入、终止时刻不计入、空档拒绝；跨取消与重新开通的重报规则。
275	func TestEventMembershipAcrossSegments(t *testing.T) {
276		s, clk := newTestService(utc(2026, 1, 15, 12, 0))
277		mustPlan(t, s, planDef("a", 1000, 10, 5, 0))
278		mustAccount(t, s, "u")
279		mustSubscribe(t, s, "u", "a", utc(2026, 1, 1, 0, 0))
280	
281		// 开通时刻计入。
282		if _, err := s.RecordEvent(Event{AccountID: "u", EventID: "start", At: utc(2026, 1, 1, 0, 0), Quantity: 1}); err != nil {
283			t.Fatalf("event at activation: %v", err)
284		}
285	
286		mustCancel(t, s, "u") // end 2/1
287	
288		// 等待取消期间、终止前一刻仍接收。
289		clk.t = utc(2026, 1, 31, 23, 59)
290		if _, err := s.RecordEvent(Event{AccountID: "u", EventID: "last", At: utc(2026, 1, 31, 23, 59), Quantity: 1}); err != nil {
291			t.Fatalf("event just before end: %v", err)
292		}
293		// 终止时刻不计入。
294		clk.t = utc(2026, 2, 1, 0, 0)
295		if _, err := s.RecordEvent(Event{AccountID: "u", EventID: "at-end", At: utc(2026, 2, 1, 0, 0), Quantity: 1}); !errors.Is(err, ErrEventBeforeSubscription) {
296			t.Fatalf("event at end: %v", err)
297		}
298		// 空档期间拒绝。
299		clk.t = utc(2026, 2, 20, 0, 0)
300		if _, err := s.RecordEvent(Event{AccountID: "u", EventID: "gap", At: utc(2026, 2, 10, 0, 0), Quantity: 1}); !errors.Is(err, ErrEventBeforeSubscription) {
301			t.Fatalf("event in gap: %v", err)
302		}
303	
304		// 3/1 重新开通：2 月事件仍属空档，3/1 00:00（开通时刻）计入新段。
305		mustSubscribe(t, s, "u", "a", utc(2026, 3, 1, 0, 0))
306		if _, err := s.RecordEvent(Event{AccountID: "u", EventID: "gap2", At: utc(2026, 2, 15, 0, 0), Quantity: 1}); !errors.Is(err, ErrEventBeforeSubscription) {
307			t.Fatalf("past gap after resubscribe: %v", err)
308		}
309		clk.t = utc(2026, 3, 2, 0, 0)
310		if _, err := s.RecordEvent(Event{AccountID: "u", EventID: "restart", At: utc(2026, 3, 1, 0, 0), Quantity: 1}); err != nil {
311			t.Fatalf("event at reactivation: %v", err)
312		}
313	
314		// 已接受事件原样重报，在取消和重新开通后仍成功、不重复累计。
315		old := Event{AccountID: "u", EventID: "start", At: utc(2026, 1, 1, 0, 0), Quantity: 1}
316		if r, err := s.RecordEvent(old); err != nil || r.Accepted {
317			t.Fatalf("identical replay across segments: %+v %v", r, err)
318		}
319		// 标识相同而时刻或数量不同仍报冲突。
320		if _, err := s.RecordEvent(Event{AccountID: "u", EventID: "start", At: utc(2026, 3, 1, 0, 0), Quantity: 1}); !errors.Is(err, ErrEventConflict) {
321			t.Fatalf("same id new time: %v", err)
322		}
323		if _, err := s.RecordEvent(Event{AccountID: "u", EventID: "start", At: utc(2026, 1, 1, 0, 0), Quantity: 2}); !errors.Is(err, ErrEventConflict) {
324			t.Fatalf("same id new qty: %v", err)
325		}
326		// 空档事件被拒不消耗标识：同标识之后落在订阅期间仍可上报。
327		if _, err := s.RecordEvent(Event{AccountID: "u", EventID: "gap", At: utc(2026, 3, 1, 12, 0), Quantity: 1}); err != nil {
328			t.Fatalf("rejected gap id reused in segment: %v", err)
329		}
330	}
331	
332	// TestBackfillAfterEndAndSuspension 终止后补报旧期间未出账用量；
333	// 到期欠费时仍拒绝新增，但相同重报成功。
334	func TestBackfillAfterEndAndSuspension(t *testing.T) {
335		s, clk := newTestService(utc(2026, 1, 15, 12, 0))
336		mustPlan(t, s, planDef("a", 1000, 0, 0, 0))
337		mustAccount(t, s, "u")
338		mustSubscribe(t, s, "u", "a", utc(2026, 1, 1, 0, 0))
339		old := Event{AccountID: "u", EventID: "old", At: utc(2026, 1, 10, 0, 0), Quantity: 1}
340		if _, err := s.RecordEvent(old); err != nil {
341			t.Fatal(err)
342		}
343		mustCancel(t, s, "u") // end 2/1
344	
345		// 终止后补报旧订阅期间、尚未出账的用量。
346		clk.t = utc(2026, 2, 10, 0, 0)
347		if r, err := s.RecordEvent(Event{AccountID: "u", EventID: "late", At: utc(2026, 1, 20, 0, 0), Quantity: 2}); err != nil || !r.Accepted || r.Period != jan(2026) {
348			t.Fatalf("backfill after end: %+v %v", r, err)
349		}
350		if u, _ := s.MonthlyUsage("u", jan(2026)); u.Total != 3 {
351			t.Fatalf("backfilled usage = %d, want 3", u.Total)
352		}
353	
354		// 出账后补报被拒，但已接受事件重报成功。
355		b := mustBill(t, s, "u", jan(2026))
356		if b.TotalUsage != 3 {
357			t.Fatalf("bill usage = %d, want 3", b.TotalUsage)
358		}
359		if _, err := s.RecordEvent(Event{AccountID: "u", EventID: "x", At: utc(2026, 1, 21, 0, 0), Quantity: 1}); !errors.Is(err, ErrMonthBilled) {
360			t.Fatalf("backfill billed month: %v", err)
361		}
362		if r, err := s.RecordEvent(old); err != nil || r.Accepted {
363			t.Fatalf("replay after billed+cancel: %+v %v", r, err)
364		}
365	
366		// 到期欠费时即使补报旧期间也拒绝新增。
367		mustAccount(t, s, "v")
368		mustSubscribe(t, s, "v", "a", utc(2026, 1, 1, 0, 0))
369		vOld := Event{AccountID: "v", EventID: "old", At: utc(2026, 1, 5, 0, 0), Quantity: 1}
370		if _, err := s.RecordEvent(vOld); err != nil {
371			t.Fatal(err)
372		}
373		clk.t = utc(2026, 2, 1, 0, 0)
374		mustBill(t, s, "v", jan(2026))
375		mustCancel(t, s, "v") // end 3/1，2 月仍在订阅覆盖内但尚未出账
376		clk.t = utc(2026, 2, 8, 0, 0)
377		st, _ := s.Status("v")
378		if !st.Suspended {
379			t.Fatal("v should be suspended")
380		}
381		// 覆盖内、未出账的 2 月新事件：到期欠费仍拒绝。
382		if _, err := s.RecordEvent(Event{AccountID: "v", EventID: "late", At: utc(2026, 2, 3, 0, 0), Quantity: 1}); !errors.Is(err, ErrSuspended) {
383			t.Fatalf("new event while suspended: %v", err)
384		}
385		if r, err := s.RecordEvent(vOld); err != nil || r.Accepted {
386			t.Fatalf("replay while suspended: %+v %v", r, err)
387		}
388	}
389	
390	// TestBillingAcrossCancellationAndResubscribe 取消不自动出账、空档月份失败、
391	// 各月按当时锁定条件出账，支持多次取消与重新开通且旧月份不被覆盖。
392	func TestBillingAcrossCancellationAndResubscribe(t *testing.T) {
393		s, clk := newTestService(utc(2026, 1, 15, 12, 0))
394		// 月费不同便于识别条件：a=1000，c=3000，额度均为 0、单价 0、税 0。
395		mustPlan(t, s, planDef("a", 1000, 0, 0, 0))
396		mustPlan(t, s, planDef("c", 3000, 0, 0, 0))
397		mustAccount(t, s, "u")
398		mustSubscribe(t, s, "u", "a", utc(2026, 1, 1, 0, 0))
399	
400		// 段一：1 月；1/15 取消，2/1 终止。
401		mustCancel(t, s, "u")
402		clk.t = utc(2026, 2, 1, 0, 0)
403		// 取消不自动出账。
404		if _, err := s.GetBill("u", jan(2026)); !errors.Is(err, ErrBillNotFound) {
405			t.Fatalf("auto-bill on cancel: %v", err)
406		}
407		// 旧订阅覆盖的已结束月份仍可出账，用当时锁定条件。
408		janBill := mustBill(t, s, "u", jan(2026))
409		if janBill.Terms.PlanID != "a" || janBill.MonthlyFee != 1000 {
410			t.Fatalf("jan bill: %+v", janBill)
411		}
412	
413		// 段二：3/1 重新开通（用新套餐），3/15 再取消，4/1 终止。
414		mustSubscribe(t, s, "u", "c", utc(2026, 3, 1, 0, 0))
415		clk.t = utc(2026, 3, 15, 0, 0)
416		mustCancel(t, s, "u")
417		clk.t = utc(2026, 4, 1, 0, 0)
418	
419		// 重开当月仍收完整月费；3 月账单按新段条件，1 月账单不被覆盖。
420		marBill := mustBill(t, s, "u", mar(2026))
421		if marBill.Terms.PlanID != "c" || marBill.MonthlyFee != 3000 {
422			t.Fatalf("mar bill: %+v", marBill)
423		}
424		gotJan, _ := s.GetBill("u", jan(2026))
425		if gotJan.MonthlyFee != 1000 || gotJan.Terms.PlanID != "a" {
426			t.Fatalf("jan bill overwritten: %+v", gotJan)
427		}
428		// 段间空档月份（2 月，已结束）出账失败。
429		if _, err := s.CreateBill("u", feb(2026)); !errors.Is(err, ErrBillBeforeSubscription) {
430			t.Fatalf("bill feb gap: %v", err)
431		}
432		// 终止后的 4 月等其结束后同样出账失败。
433		clk.t = utc(2026, 5, 1, 0, 0)
434		if _, err := s.CreateBill("u", apr(2026)); !errors.Is(err, ErrBillBeforeSubscription) {
435			t.Fatalf("bill apr gap: %v", err)
436		}
437	
438		// 后来修改套餐定义，已出账金额与税额不变。
439		if err := s.UpdatePlan(planDef("a", 9999, 0, 0, 1000)); err != nil {
440			t.Fatal(err)
441		}
442		gotJan, _ = s.GetBill("u", jan(2026))
443		if gotJan.MonthlyFee != 1000 || gotJan.TotalDue != 1000 {
444			t.Fatalf("jan bill changed after plan update: %+v", gotJan)
445		}
446	}
447	
448	// TestResubscribeRules 重新开通的时刻限制、快照、当月完整条款，
449	// 以及事件/付款标识不重置。
450	func TestResubscribeRules(t *testing.T) {
451		s, clk := newTestService(utc(2026, 1, 15, 12, 0))
452		mustPlan(t, s, planDef("a", 1000, 10, 5, 0))
453		mustPlan(t, s, planDef("c", 3000, 30, 9, 0))
454		mustAccount(t, s, "u")
455		mustSubscribe(t, s, "u", "a", utc(2026, 1, 1, 0, 0))
456		if _, err := s.RecordEvent(Event{AccountID: "u", EventID: "keep", At: utc(2026, 1, 10, 0, 0), Quantity: 1}); err != nil {
457			t.Fatal(err)
458		}
459		mustCancel(t, s, "u") // end 2/1
460		clk.t = utc(2026, 2, 1, 0, 0)
461	
462		// 开通时刻早于上次终止时刻：拒绝。
463		if err := s.Subscribe("u", "c", utc(2026, 1, 31, 23, 59)); !errors.Is(err, ErrResubscribeBeforeEnd) {
464			t.Fatalf("resubscribe before end: %v", err)
465		}
466		// 失败不留部分变更。
467		st, _ := s.Status("u")
468		if st.Subscribed {
469			t.Fatalf("partial subscription after failed resubscribe")
470		}
471		// 恰为上次终止时刻：允许，保存重新开通时的套餐条件。
472		mustSubscribe(t, s, "u", "c", utc(2026, 2, 1, 0, 0))
473		st, _ = s.Status("u")
474		if !st.Subscribed || st.CurrentTerms.PlanID != "c" || st.CurrentTerms.MonthlyFee != 3000 {
475			t.Fatalf("status after resubscribe: %+v", st)
476		}
477		// 有尚未终止的订阅时拒绝再次开通。
478		if err := s.Subscribe("u", "a", utc(2026, 2, 1, 0, 0)); !errors.Is(err, ErrSubscriptionExists) {
479			t.Fatalf("dup resubscribe: %v", err)
480		}
481	
482		// 事件标识不随重新开通重置：旧标识冲突规则依旧。
483		if _, err := s.RecordEvent(Event{AccountID: "u", EventID: "keep", At: utc(2026, 2, 5, 0, 0), Quantity: 1}); !errors.Is(err, ErrEventConflict) {
484			t.Fatalf("event id reset by resubscribe: %v", err)
485		}
486	
487		// 付款标识不随重新开通重置。
488		janBill := mustBill(t, s, "u", jan(2026))
489		if _, err := s.RecordPayment("u", "pay1", jan(2026), janBill.TotalDue); err != nil {
490			t.Fatal(err)
491		}
492		clk.t = utc(2026, 3, 1, 0, 0)
493		febBill := mustBill(t, s, "u", feb(2026))
494		if febBill.MonthlyFee != 3000 {
495			t.Fatalf("feb (resubscribe month) bill = %+v", febBill)
496		}
497		if _, err := s.RecordPayment("u", "pay1", feb(2026), 1); !errors.Is(err, ErrPaymentConflict) {
498			t.Fatalf("payment id reset by resubscribe: %v", err)
499		}
500	}
501	
502	// TestResubscribeWithOldDebt 重新开通不清旧欠费；欠费停用规则照旧。
503	func TestResubscribeWithOldDebt(t *testing.T) {
504		s, clk := newTestService(utc(2026, 1, 20, 12, 0))
505		mustPlan(t, s, planDef("a", 1000, 0, 0, 0))
506		mustAccount(t, s, "u")
507		mustSubscribe(t, s, "u", "a", utc(2026, 1, 1, 0, 0))
508		clk.t = utc(2026, 2, 1, 0, 0)
509		mustBill(t, s, "u", jan(2026))
510		clk.t = utc(2026, 2, 8, 0, 0)
511		if st, _ := s.Status("u"); !st.Suspended {
512			t.Fatal("should be suspended")
513		}
514		mustCancel(t, s, "u") // end 3/1
515		clk.t = utc(2026, 3, 1, 0, 0)
516	
517		// 带着旧欠费重新开通：允许，但停用状态依旧，新用量仍被拒绝。
518		mustSubscribe(t, s, "u", "a", utc(2026, 3, 1, 0, 0))
519		st, _ := s.Status("u")
520		if !st.Subscribed || !st.Suspended {
521			t.Fatalf("resubscribe cleared debt: %+v", st)
522		}
523		clk.t = utc(2026, 3, 2, 0, 0)
524		if _, err := s.RecordEvent(Event{AccountID: "u", EventID: "m", At: utc(2026, 3, 1, 12, 0), Quantity: 1}); !errors.Is(err, ErrSuspended) {
525			t.Fatalf("new usage with old debt: %v", err)
526		}
527		// 结清旧债只解除停用，订阅保持有效（不改变其生命周期）。
528		if _, err := s.RecordPayment("u", "p", jan(2026), 1000); err != nil {
529			t.Fatal(err)
530		}
531		st, _ = s.Status("u")
532		if st.Suspended || !st.Subscribed {
533			t.Fatalf("status after settling old debt: %+v", st)
534		}
535		if _, err := s.RecordEvent(Event{AccountID: "u", EventID: "m", At: utc(2026, 3, 1, 12, 0), Quantity: 1}); err != nil {
536			t.Fatalf("usage after debt cleared: %v", err)
537		}
538	}
539	
540	// TestConcurrentCancellation 并发重复取消只有一次生效，终止时刻一致；
541	// 取消/撤回/换套餐/用量/出账混跑后状态自洽，账单金额内部一致。
542	func TestConcurrentCancellation(t *testing.T) {
543		s, clk := newTestService(utc(2026, 1, 15, 12, 0))
544		mustPlan(t, s, planDef("a", 1000, 5, 10, 0))
545		mustPlan(t, s, planDef("b", 2000, 5, 20, 0))
546		mustAccount(t, s, "u")
547		mustSubscribe(t, s, "u", "a", utc(2026, 1, 1, 0, 0))
548	
549		const n = 64
550		var wg sync.WaitGroup
551		var mu sync.Mutex
552		var created int
553		ends := make([]time.Time, 0, n)
554		wg.Add(n)
555		for i := 0; i < n; i++ {
556			go func() {
557				defer wg.Done()
558				r, err := s.CancelSubscription("u")
559				if err != nil {
560					t.Errorf("concurrent cancel: %v", err)
561					return
562				}
563				mu.Lock()
564				if r.Cancelled {
565					created++
566				}
567				ends = append(ends, r.Cancellation.EndAt)
568				mu.Unlock()
569			}()
570		}
571		wg.Wait()
572		if created != 1 {
573			t.Fatalf("cancellations created = %d, want 1", created)
574		}
575		for _, e := range ends {
576			if !e.Equal(utc(2026, 2, 1, 0, 0)) {
577				t.Fatalf("end = %v, want 2026-02-01", e)
578			}
579		}
580	
581		// 撤回后再混跑取消/撤回/换套餐/撤回换套餐/用量，结果必须对应某个先后顺序。
582		if err := s.UndoCancelSubscription("u"); err != nil {
583			t.Fatal(err)
584		}
585		wg.Add(n * 4)
586		for i := 0; i < n; i++ {
587			go func() { defer wg.Done(); _, _ = s.CancelSubscription("u") }()
588			go func() { defer wg.Done(); _ = s.UndoCancelSubscription("u") }()
589			go func() { defer wg.Done(); _, _ = s.SchedulePlanChange("u", "b") }()
590			go func() { defer wg.Done(); _ = s.CancelPlanChange("u") }()
591		}
592		wg.Wait()
593		st, _ := s.Status("u")
594		if !st.Subscribed {
595			t.Fatalf("not subscribed in January: %+v", st)
596		}
597		// 不变量：取消安排与换套餐安排不能同时存在。
598		if st.ScheduledEnd != nil && st.PendingChange != nil {
599			t.Fatalf("both cancellation and plan change pending: %+v", st)
600		}
601	
602		// 1 月先补一笔用量，推进到 2 月并发出账：1 月账单永远适用 a，金额自洽。
603		if _, err := s.RecordEvent(Event{AccountID: "u", EventID: "base", At: utc(2026, 1, 12, 0, 0), Quantity: 8}); err != nil {
604			t.Fatal(err)
605		}
606		clk.t = utc(2026, 2, 1, 0, 0)
607		bills := make([]Bill, n)
608		wg.Add(n)
609		for i := 0; i < n; i++ {
610			go func(i int) {
611				defer wg.Done()
612				b, err := s.CreateBill("u", jan(2026))
613				if err != nil {
614					t.Errorf("concurrent bill: %v", err)
615					return
616				}
617				bills[i] = b
618			}(i)
619		}
620		wg.Wait()
621		var first Bill
622		for i, b := range bills {
623			if i == 0 {
624				first = b
625				continue
626			}
627			if b != first {
628				t.Fatalf("bills differ:\n%+v\n%+v", first, b)
629			}
630		}
631		if first.Terms.PlanID != "a" || first.MonthlyFee != 1000 || first.OverageUnits != 3 ||
632			first.OverageFee != 30 || first.TotalDue != 1030 {
633			t.Fatalf("jan bill inconsistent: %+v", first)
634		}
635	}
